//! Channel state persisted by Icinga Notifications.

use serde::{Deserialize, Serialize};

use crate::error::ChannelError;

/// The allowed length of a state value, in characters.
const VALUE_LEN: std::ops::RangeInclusive<usize> = 1..=4096;

/// The state of one channel, incident and contact, as received in a request.
///
/// The key is opaque. Return a [`State`] with a new value from the
/// notification handler to store it.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
pub struct State {
    /// Identifies the state; opaque and never generated by the channel.
    #[serde(rename = "state_key")]
    pub key: StateKey,
    /// The previously stored value, empty if nothing has been stored yet.
    pub value: String,
}

/// The opaque key of a [`State`].
#[derive(Debug, Clone, PartialEq, Eq, Deserialize, Serialize)]
#[serde(transparent)]
pub struct StateKey(String);

/// The state to store, returned in a `DeliveryResult`.
#[derive(Debug, Clone, PartialEq, Eq, Serialize)]
pub struct StateUpdate {
    #[serde(rename = "state_key")]
    key: StateKey,
    value: String,
}

impl State {
    /// A new value for this state, keeping the received key.
    ///
    /// The value must be 1 to 4096 characters long.
    pub fn update(&self, value: impl Into<String>) -> Result<StateUpdate, ChannelError> {
        let value = value.into();
        let len = value.chars().count();
        if !VALUE_LEN.contains(&len) {
            return Err(ChannelError::new(format!(
                "state value has {len} characters, expected {} to {}",
                VALUE_LEN.start(),
                VALUE_LEN.end()
            )));
        }
        Ok(StateUpdate {
            key: self.key.clone(),
            value,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn state() -> State {
        serde_json::from_value(json!({"state_key": "k", "value": ""})).unwrap()
    }

    #[test]
    fn rejects_values_out_of_range() {
        for len in [0, 4097] {
            let error = state().update("a".repeat(len)).unwrap_err();
            let message = error.message();
            assert!(message.contains(&len.to_string()), "{message}");
            assert!(message.contains("1 to 4096"), "{message}");
        }
    }

    #[test]
    fn counts_characters_not_bytes() {
        assert!(state().update("ä".repeat(4096)).is_ok());
    }

    #[test]
    fn keeps_received_key() {
        for len in [1, 4096] {
            let update = state().update("a".repeat(len)).unwrap();
            assert_eq!(
                serde_json::to_value(update).unwrap(),
                json!({"state_key": "k", "value": "a".repeat(len)})
            );
        }
    }
}
